/* Default collections, run after the collections tables exist (part 95). Every new store starts with two collections, as a Shopify store does: Home page (slug frontpage, hand-picked, empty) and All products (slug all, smart, its one condition true of every product). A trigger on creators makes them as a store is made, whichever way it was made; a store that already has a collection by either address keeps its own. Existing stores are not changed: no rows are added to them. Until it runs, the app makes the two when onboarding finishes. Safe to run again. */
CREATE OR REPLACE FUNCTION public.storelib_default_collections(p_creator uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $fn$ BEGIN IF to_regclass('public.product_collections') IS NULL THEN RETURN; END IF; INSERT INTO public.product_collections (creator_id, title, slug, kind, rules, match, sort, published) VALUES (p_creator, 'Home page', 'frontpage', 'manual', '[]'::jsonb, 'all', 'manual', true), (p_creator, 'All products', 'all', 'smart', '[{"field":"price","op":"greater_than","value":"-1"}]'::jsonb, 'all', 'newest', true) ON CONFLICT (creator_id, slug) DO NOTHING; END $fn$;
REVOKE ALL ON FUNCTION public.storelib_default_collections(uuid) FROM PUBLIC, anon, authenticated;
CREATE OR REPLACE FUNCTION public.storelib_default_collections_on_creator() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $fn$ BEGIN PERFORM public.storelib_default_collections(NEW.id); RETURN NEW; EXCEPTION WHEN others THEN RAISE WARNING 'default collections: %', SQLERRM; RETURN NEW; END $fn$;
REVOKE ALL ON FUNCTION public.storelib_default_collections_on_creator() FROM PUBLIC, anon, authenticated;
DO $do$ BEGIN IF to_regclass('public.creators') IS NULL THEN RAISE NOTICE 'default collections: the creators table is not there yet.'; RETURN; END IF; DROP TRIGGER IF EXISTS creators_default_collections ON public.creators; CREATE TRIGGER creators_default_collections AFTER INSERT ON public.creators FOR EACH ROW EXECUTE FUNCTION public.storelib_default_collections_on_creator(); END $do$;
notify pgrst, 'reload schema';
